#[derive(TypeName)]
struct Widget;

#[derive(TypeName)]
#[allow(dead_code)]
enum Shape<T> {
    Circle(T),
}

#[test]
fn derive_works() {
    assert_eq!(Widget::type_name(), "Widget");
    assert_eq!(Shape::<u8>::type_name(), "Shape");
}
EOF
cargo test 2>&1 | grep -E "^(test |error|warning|test result)"; cargo clippy --all-targets 2>&1 | tail -2

